#!/usr/bin/env bash
#
# Tabletop AV & Audio Recording Setup Wizard
# Walks through physical HDMI extended desktop routing and Blue Snowball mic setup on the Raspberry Pi / Home Assistant.
# Generated by the /wizard skill.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard walks you through physical HDMI routing, TV soundbar audio,\n' "$DIM"
  printf '  and central room recording on the Blue Snowball USB microphone.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v open        >/dev/null 2>&1; then open "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "Visit URL manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Tabletop AV Setup Complete%s\n' "$BOLD" "$GREEN" "$RESET"
  note "Physical pipeline is verified and ready for live play."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Tabletop AV Pipeline Configuration
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

banner "Sea of Fortune Tabletop AV Setup"

stage "HDMI Extended Display & Audio Routing"
say "Connect your GM Laptop to the table TV using a single high-speed HDMI cable."
step "Set macOS display settings to 'Extend Display' (not Mirror)."
step "Drag Window 2 (Player Handouts / Tactical Maps) to the TV display."
step "Set System Audio Output to the HDMI TV / Soundbar."
pause "Confirm HDMI display and audio are active?"

stage "Home Assistant & Raspberry Pi Audio Host"
say "Verify the central Raspberry Pi is powered and connected to the local network."
step "Check that the Blue Snowball USB condenser microphone is plugged into the Pi USB port."
step "Ensure the Blue Snowball is set to Setting 1 (Cardioid) or Setting 2 (-10dB Cardioid if audio peaks)."
step "Open Home Assistant dashboard to verify USB audio device detection."
open_url "http://homeassistant.local:8123"
pause "Confirm Blue Snowball is detected by the Raspberry Pi?"

stage "Master 4-Hour MP3 Recording Path"
say "Configure the local session recording path on the Raspberry Pi storage."
step "Verify the storage mount path for live recordings (e.g., /media/recordings/sessions/)."
step "Confirm disk write permissions and free storage space (>5GB recommended for uncompressed backup)."
pause "Confirm recording directory is ready?"

stage "Web Audio Browser Permissions & Output Test"
say "Verify the laptop browser Web Audio mixer permissions."
step "Open the Sea of Fortune GM Screen Web App."
open_url "https://script.google.com/macros/s/AKfycbwj8LTo82ezIm21xIfEi3mKwXKDoNMQgkif9w-raC3cRtF3Dtoy6863i-FLSAuxpe6Akw/exec"
step "Verify ambient audio loop playback routes through HDMI to the TV soundbar."
step "Verify triggering an SFX ducks the ambient score cleanly."
pause "Confirm audio mixer output is verified?"

finish
}

run_wizard "$@"; exit
